`timescale 1ns / 1ps

// mul_core s_dralm6: signed 8 x 8 -> 16, signed DR-ALM-6, paper sign units (Yin 2021, = chip dralm_t6).
// Reference model: approx/mulbench.py.
// Generated by python3 -m src_gan_tsmc65.approx.mulbench (do not edit).

// logarithmic converter: x (> 0) -> {k, x_t}, k = leading-one position, x_t = the
// 4 bits after the leading one and a forced 1 (dynamic truncation, t = 6)
module dralm_t6_log (
    input  wire [6:0] x,
    output wire [7:0] l
);
    reg [2:0] k;
    integer i;
    always @* begin
        k = 0;
        for (i = 1; i < 7; i = i + 1)
            if (x[i]) k = i;
    end
    wire [6:0] xs = x << (6 - k);       // leading one to bit 6
    assign l = {k, xs[5:2], 1'b1};
endmodule

// antilogarithmic converter + shifter: P = {1, L[t-2:0]} * 2^(L[top:t-1] - (t-1)),
// bits below the binary point dropped
module dralm_t6_antilog (
    input  wire [8:0] l,
    output wire [13:0] p
);
    wire [5:0] mant = {1'b1, l[4:0]};
    wire [3:0] e = l[8:5];
    wire [18:0] s = {{(13){1'b0}}, mant} << e;
    assign p = s[18:5];
endmodule

module mul_core (
    input  wire signed [7:0]  a,
    input  wire signed [7:0]  b,
    output wire signed [15:0] p
);
    // sign detector: |x| ~ ~x | 1 for x < 0 (one's complement, LSB OR-ed with 1)
    wire [6:0] ma = (a[6:0] ^ {7{a[7]}}) | {6'd0, a[7]};
    wire [6:0] mb = (b[6:0] ^ {7{b[7]}}) | {6'd0, b[7]};
    wire [7:0] la, lb;
    dralm_t6_log u_la (.x(ma), .l(la));
    dralm_t6_log u_lb (.x(mb), .l(lb));
    // adder + compensation: both x_t LSBs are 1 and +2^-(t-1) is added, so the sum LSB
    // is 1 and the upper bits get a carry-in of 1
    wire [7:0] hi = la[7:1] + lb[7:1] + 1'b1;
    wire [8:0] l = {hi, 1'b1};
    wire [13:0] m;
    dralm_t6_antilog u_al (.l(l), .p(m));
    wire zero = ~|a | ~|b;
    wire neg = a[7] ^ b[7];
    // sign set: -P ~ ~P | 1
    wire [15:0] pm = {2'b00, m};
    assign p = zero ? 16'sd0 : (neg ? $signed(~pm | 16'd1) : $signed(pm));
endmodule
